"""Who may change which contributor folder, and the CODEOWNERS file that enforces it."""

from __future__ import annotations

from pathlib import PurePosixPath

from progress_bot.models import Contributor

CODEOWNERS_HEADER = """\
# Generated by `progress-bot codeowners`. Do not edit by hand.
# Sentinels own everything; each contributor folder is owned by its contributor and
# their mentor, so a contributor's PR needs their mentor's (or a Sentinel's) approval.
"""


def sentinels(roster: list[Contributor]) -> list[str]:
    return sorted(
        (c.login for c in roster if c.profile.level == "sentinel" and c.profile.active),
        key=str.lower,
    )


def codeowners(roster: list[Contributor]) -> str:
    leads = sentinels(roster)
    lines = [CODEOWNERS_HEADER]
    if leads:
        lines.append("* " + " ".join(f"@{s}" for s in leads))
        lines.append("")
    for c in sorted(roster, key=lambda c: c.login.lower()):
        owners = [c.login]
        if c.profile.mentor:
            owners.append(c.profile.mentor)
        else:
            owners += [s for s in leads if s.lower() != c.login.lower()]
        owners = [f"@{o}" for o in dict.fromkeys(owners)]
        lines.append(f"/contributors/{c.folder.name}/ {' '.join(owners)}")
    return "\n".join(lines).rstrip() + "\n"


def check_ownership(
    author: str,
    changed: list[str],
    base: list[Contributor],
    head: list[Contributor],
) -> list[str]:
    """Problems with a PR by `author` changing `changed` files.

    `base` is the roster on the target branch, so a PR cannot make its own
    author a Sentinel and then pass this check.
    """
    me = author.lower()
    base_by = {c.login.lower(): c for c in base}
    head_by = {c.login.lower(): c for c in head}
    leads = {s.lower() for s in sentinels(base)}
    if not leads or me in leads:
        return []  # Sentinels may change anything; with none yet, the repo is being set up
    mentees = {c.login.lower() for c in base if c.profile.mentor and c.profile.mentor.lower() == me}

    problems: list[str] = []
    for name in changed:
        parts = PurePosixPath(name).parts
        if not parts or parts[0] != "contributors":
            continue  # everything else is covered by normal code review
        if len(parts) < 3:
            problems.append(f"{name}: only Sentinels can change the contributors/ folder itself")
            continue
        folder = parts[1].lower()
        if folder in mentees:
            continue
        if folder != me:
            problems.append(f"{name}: @{author} can only change contributors/{author}/")
            continue
        if parts[2] != "profile.md":
            continue
        before, after = base_by.get(me), head_by.get(me)
        if after is None:
            continue  # broken profile: validation reports it
        if before is None:
            if after.profile.level == "sentinel":
                problems.append(f"{name}: only a Sentinel can add a new Sentinel")
        else:
            if before.profile.level != after.profile.level:
                problems.append(
                    f"{name}: level changes ({before.profile.level} → {after.profile.level}) "
                    "must be made by a Sentinel"
                )
            if (before.profile.mentor or "").lower() != (after.profile.mentor or "").lower():
                problems.append(f"{name}: mentor changes must be made by a Sentinel")
    return problems
